/**
 * HEALTHPLEX — PDF & CSV export verification.
 * Exercises the ACTUAL modules used by the web app (src/lib/pdf.ts, src/lib/csv.ts),
 * not copies of them. Run with: node --experimental-strip-types scripts/test-pdf-export.mjs
 *
 * jsPDF in Node cannot trigger a browser "Save", so doc.save() is intentionally NOT
 * called here; buildAttendancePdf() (the exact code path exportAttendancePdf uses)
 * returns the jsPDF instance and we assert on the generated bytes/pages instead.
 */
import assert from "node:assert/strict";
import { buildAttendancePdf } from "../src/lib/pdf.ts";
import { csvEscape, toCsv, parseCsv } from "../src/lib/csv.ts";

let passed = 0;
function ok(name) {
  passed += 1;
  console.log(`  ✓ ${name}`);
}

const REAL_ROW = ["1", "OMRAJNEXUS", "26BT04074", "—", 18, 0, 18, 0, 10, 90, "45.0"];
const COLUMNS = ["#", "Name", "Enrollment", "Dept", "Eligible", "Present", "Absent", "Incomplete", "%", "Minutes", "Avg"];

// ---------- 1. multi-page PDF with real-looking rows ----------
const manyRows = Array.from({ length: 180 }, (_, i) => [
  String(i + 1),
  `Student ${i + 1}`,
  `26BT${String(10000 + i).padStart(5, "0")}`,
  i % 3 === 0 ? "Computer" : "Mechanical",
  18,
  (i * 7) % 19,
  18 - ((i * 7) % 19),
  i % 17 === 0 ? 1 : 0,
  `${(((i * 7) % 19) / 18 * 100).toFixed(1)}%`,
  (i * 37) % 400,
  "44.5",
]);
const doc = await buildAttendancePdf({
  title: "Attendance Frequency & Reports",
  subtitle: "01 Nov 2026 — 30 Nov 2026 · 180 students · generated by Test Harness",
  columns: COLUMNS,
  rows: manyRows,
  filename: "report.pdf",
  summaryLines: [
    "Overall: 2,160 present student-days of 3,240 eligible (66.7%) · 18,500 verified gym minutes",
    "Period: 01 Nov 2026 — 30 Nov 2026 · 18 eligible operating days · Asia/Kolkata",
  ],
});
const pages = doc.getNumberOfPages();
assert.ok(pages >= 2, `expected pagination across multiple pages, got ${pages}`);
const bytes = Buffer.from(doc.output("arraybuffer"));
assert.equal(bytes.subarray(0, 5).toString(), "%PDF-", "PDF header missing");
assert.ok(bytes.length > 20000, `PDF suspiciously small: ${bytes.length} bytes`);
ok(`multi-page PDF builds (${pages} pages, ${bytes.length} bytes, %PDF header)`);

// ---------- 2. single-row + summary statistics PDF (monthly report shape) ----------
const docSingle = await buildAttendancePdf({
  title: "Attendance register",
  subtitle: "01 Nov 2026 — 30 Nov 2026 · 1 record · real export shape",
  columns: COLUMNS,
  rows: [REAL_ROW],
  filename: "monthly.pdf",
  summaryLines: ["Overall: 0.0% attendance · GSFC University"],
});
assert.equal(docSingle.getNumberOfPages(), 1);
assert.equal(Buffer.from(docSingle.output("arraybuffer")).subarray(0, 5).toString(), "%PDF-");
ok("single-row monthly PDF builds on one page");

// ---------- 3. empty dataset handled gracefully ----------
const docEmpty = await buildAttendancePdf({
  title: "Attendance Frequency & Reports",
  subtitle: "01 Nov 2026 — 30 Nov 2026 · 0 students",
  columns: COLUMNS,
  rows: [],
  filename: "empty.pdf",
});
assert.equal(docEmpty.getNumberOfPages(), 1);
assert.equal(Buffer.from(docEmpty.output("arraybuffer")).subarray(0, 5).toString(), "%PDF-");
ok("empty dataset produces a valid branded PDF (no autoTable crash)");

// ---------- 4. functional autoTable API is the one being exercised ----------
// (this very file imports buildAttendancePdf which uses autoTable(doc, ...);
//  a bare side-effect import was the production bug — assert the old pattern stays gone)
import { readFileSync } from "node:fs";
const pdfSrc = readFileSync(new URL("../src/lib/pdf.ts", import.meta.url), "utf8");
assert.match(pdfSrc, /autoTable\(doc,/, "pdf.ts must call autoTable(doc, …)");
assert.doesNotMatch(pdfSrc, /\bdoc\.autoTable\s*\(/, "pdf.ts must NOT rely on the removed prototype method");
ok("source uses the supported jspdf-autotable v5 functional API");

// ---------- 5. CSV correctness ----------
assert.equal(csvEscape('a,"b"'), '"a,""b"""');
assert.equal(csvEscape("plain"), "plain");
assert.equal(csvEscape(null), "");
assert.equal(csvEscape(42), "42");
const csv = toCsv([
  ["HEALTHPLEX · GSFC University", "Attendance Frequency & Reports", "November 2026"],
  ["#", "Name", "Notes"],
  ["1", 'Omraj, "OJ" Nexus', "line one\nline two"],
]);
assert.ok(csv.includes('1,"Omraj, ""OJ"" Nexus","line one\nline two"'), "quoted multi-line cell must round-trip");
assert.ok(csv.split("\n")[0].startsWith("HEALTHPLEX"));
ok("CSV escaping survives commas, quotes and embedded newlines");

// round trip: quoted multi-line cell survives parse
const parsed = parseCsv("a,b\n1,\"x, y\"");
assert.deepEqual(parsed, [{ a: "1", b: "x, y" }]);
ok("CSV parser round-trips quoted cells");

console.log(`\nAll ${passed} PDF/CSV export checks passed.`);
